@page "/board"
@using sv_d8aae864e7684cae869aa19d243ad87b
@using sv_d8aae864e7684cae869aa19d243ad87b.Components.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

@if (isLoading)
{
    <p class="board-loading">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <div class="board-error">
        <p>@errorMessage</p>
        <button class="btn" @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardSummaryBar Tasks="allTasks" />
    <BoardSearchBar SearchTerm="@searchTerm" OnSearchChanged="HandleSearchChanged" />

    <div class="board-columns">
        @for (int i = 0; i < columns.Length; i++)
        {
            var col = columns[i];
            var colTasks = FilteredTasksForStatus(col);
            <BoardColumn ColumnName="@col"
                         ColumnStatus="@col"
                         Tasks="colTasks"
                         CanMoveLeft="i > 0"
                         CanMoveRight="i < columns.Length - 1"
                         OnMoveTask="HandleMoveTask"
                         OnTaskCreated="HandleTaskCreated" />
        }
    </div>
}

@code {
    private static readonly string[] columns = { "To Do", "In Progress", "Done" };

    private List<TaskItem> allTasks = new();
    private string searchTerm = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        isLoading = true;
        errorMessage = null;
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> FilteredTasksForStatus(string status)
    {
        var filtered = allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            filtered = filtered.Where(t => t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));
        }
        return filtered.ToList();
    }

    private void HandleSearchChanged(string term)
    {
        searchTerm = term;
    }

    private async Task HandleMoveTask((TaskItem Task, string Direction) move)
    {
        var currentIndex = Array.IndexOf(columns, move.Task.Status);
        var newIndex = move.Direction == "left" ? currentIndex - 1 : currentIndex + 1;
        if (newIndex < 0 || newIndex >= columns.Length) return;

        var newStatus = columns[newIndex];
        try
        {
            await TaskService.UpdateTaskStatusAsync(move.Task.Id, newStatus);
            // Update local state
            var index = allTasks.FindIndex(t => t.Id == move.Task.Id);
            if (index >= 0)
            {
                var old = allTasks[index];
                allTasks[index] = old with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private void HandleTaskCreated(TaskItem task)
    {
        allTasks.Add(task);
    }
}

